      const items = page.locator('#na .na-item');
      expect(await items.count()).toBeGreaterThanOrEqual(NA_SEV.length);
      const links = await items.evaluateAll(is => is.map(i => { const a = i.querySelector(':scope > a.na-link'); return a ? a.getAttribute('href') : null; }));
      expect(links.filter(l => !l), 'every Needs-Attention item is a link').toEqual([]);
      for (const l of links) expect((await request.get(D + l.split(/[?#]/)[0])).status(), l).toBe(200);
      expect(await page.locator('#na .na-sum a').count(), 'counts per group are links').toBe(NA_SEV.length);
      await expect(page.locator('#na')).toContainText('صورة الصفحة الرئيسية كبيرة وتبطئ تحميل الصفحة');
      const adv = page.locator('#na details.adv').first();
      await expect(adv.locator('summary')).toHaveText('تفاصيل متقدمة');
      await expect(adv.locator('p')).toBeHidden();
      await adv.locator('summary').click();
      await expect(page.locator('#na details.adv[open] p').first()).toBeVisible();
      await expect(page.locator('#na')).toContainText('Hero LCP resource 2.8MB');
      expect(await page.locator('#live .tile').count()).toBeGreaterThanOrEqual(2);
      await expect(page.locator('#live')).toContainText('يبدأ التالي');
      await expect(page.locator('#live')).toContainText('ينتهي التالي');
