      for (const s of ['GA4', 'Search Console', 'Google Business Profile']) await expect(page.locator(`#sources .pi[data-src="${s}"]`)).toContainText('PENDING INTEGRATION');
      for (const t of ['تغيير سعر صنف', 'تغيير توفر صنف', 'تعديل ساعات فرع', 'تشغيل أو إيقاف حملة', 'رفع صورة', 'مراجعة صحة الموقع'])
        await expect(page.getByRole('link', { name: t, exact: true }), `phone task (M26): ${t}`).toBeVisible();
