      await expect(page.locator('#source .pi[data-src=GA4]')).toContainText('PENDING INTEGRATION');
      expect(await page.locator('#range option').allTextContents()).toEqual(['اليوم', 'أمس', 'آخر 7 أيام', 'آخر 30 يومًا', 'هذا الشهر', 'الشهر السابق', 'فترة مخصصة']);
